block serv_w   concrete
block crew_w   corridor
block med_w    clinic
block off_w    silver
block elite_w  oak
block marble_w marble
# The floors: a slab's top is the floor of the deck on it, its underside the
# ceiling of the deck below.
block fl_sump  ceil grate ceil
block fl_serv  ceil grime ceil
block fl_crew  ceil floor ceil
block fl_med   ceil tiles ceil
block fl_farm  ceil grate ceil
block fl_off   ceil green ceil
block fl_elite ceil carpet ceil
block fl_prom  ceil stone marble
block fl_cmd   ceil grip ceil
block fl_roof  ceil steel ceil
